using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for high throughput on large spans.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (!Vector.IsHardwareAccelerated || values.Length < Vector<float>.Count * 2)
            return FindMinMaxScalar(values);

        ref float start = ref MemoryMarshal.GetReference(values);
        int vectorCount = Vector<float>.Count;
        int onePassLength = values.Length - (values.Length % vectorCount);

        var vMin = new Vector<float>(values[0]);
        var vMax = vMin;

        // Process two vectors per iteration to improve instruction-level parallelism
        int twoVecStride = vectorCount * 2;
        int twoPassLength = values.Length - (values.Length % twoVecStride);
        int i = 0;

        for (; i < twoPassLength; i += twoVecStride)
        {
            var v0 = new Vector<float>(values.Slice(i, vectorCount));
            var v1 = new Vector<float>(values.Slice(i + vectorCount, vectorCount));
            vMin = Vector.Min(vMin, Vector.Min(v0, v1));
            vMax = Vector.Max(vMax, Vector.Max(v0, v1));
        }

        // Handle remaining full vector
        for (; i < onePassLength; i += vectorCount)
        {
            var v = new Vector<float>(values.Slice(i, vectorCount));
            vMin = Vector.Min(vMin, v);
            vMax = Vector.Max(vMax, v);
        }

        // Reduce vectors to scalars
        float min = vMin[0];
        float max = vMax[0];
        for (int j = 1; j < vectorCount; j++)
        {
            if (vMin[j] < min) min = vMin[j];
            if (vMax[j] > max) max = vMax[j];
        }

        // Handle trailing elements
        for (; i < values.Length; i++)
        {
            float val = Unsafe.Add(ref start, i);
            if (val < min) min = val;
            if (val > max) max = val;
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }
}

